:root {
  --primary: #02838D;
  --primary-dark: #01626A;
  --secondary: #FF6F61;
  --secondary-hover: #E85F52;
  --text-dark: #231F20;
  --text-light: #5A5A5A;
  --bg-color: #FAFAFA;
  --bg-card: #FFFFFF;
  --bg-subtle: #F0F4F4;
  --border: #E0E0E0;

  --font-main: 'Inter', system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 2px 4px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --max-width: 1200px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-main);
  color: var(--text-dark);
  background-color: var(--bg-color);
  line-height: 1.6;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  color: var(--primary-dark);
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 20px;
}

.btn {
  display: inline-block;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  border: none;
  transition: background 0.2s, transform 0.1s;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--primary);
  color: white;
}
.btn-primary:hover {
  background-color: var(--primary-dark);
  color: white;
}

.btn-secondary {
  background-color: var(--secondary);
  color: white;
}
.btn-secondary:hover {
  background-color: var(--secondary-hover);
  color: white;
}

/* Header & Nav */
header {
  background: var(--bg-card);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.credibility-ticker {
  background: var(--text-dark);
  color: white;
  padding: 8px 0;
  font-size: 0.85rem;
  overflow: hidden;
  white-space: nowrap;
  display: flex;
}

.ticker-content {
  display: flex;
  gap: 40px;
  animation: ticker 25s linear infinite;
  padding-left: 100%;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ticker-item svg {
  fill: var(--primary);
  width: 16px;
  height: 16px;
}

@keyframes ticker {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.5px;
}

.main-nav {
  display: flex;
  gap: 24px;
}

.nav-item {
  font-weight: 600;
  color: var(--text-dark);
  cursor: pointer;
  padding: 8px 0;
  position: relative;
}

.nav-item:hover {
  color: var(--primary);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--bg-card);
  width: 800px;
  padding: 30px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  display: none;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  border-top: 3px solid var(--primary);
}

.nav-item:hover .mega-menu,
.nav-item:focus-within .mega-menu,
.mega-menu.active {
  display: grid;
}

.mega-menu h4 {
  font-size: 0.9rem;
  color: var(--text-light);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.mega-menu ul {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.mega-menu a {
  color: var(--text-dark);
  font-size: 0.95rem;
}
.mega-menu a:hover {
  color: var(--primary);
  text-decoration: underline;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Hero Section */
.hero-section {
  padding: 60px 0;
}
.hero-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 40px;
}

.hero-main {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
}

.hero-image {
  background: var(--bg-subtle);
  height: 400px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-badge {
  position: absolute;
  top: 20px;
  left: 20px;
  background: var(--secondary);
  color: white;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.hero-content {
  padding: 32px;
}

.hero-content h1 {
  font-size: 2.5rem;
  line-height: 1.2;
  margin-bottom: 16px;
  color: var(--text-dark);
}

.hero-content p {
  font-size: 1.1rem;
  color: var(--text-light);
  margin-bottom: 24px;
}

.trending-sidebar h3 {
  font-size: 1.25rem;
  margin-bottom: 20px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--border);
}

.trending-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.trending-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.trending-category {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--primary);
  text-transform: uppercase;
}

.trending-title {
  font-weight: 600;
  font-size: 1.05rem;
  line-height: 1.4;
  color: var(--text-dark);
}
.trending-title:hover {
  color: var(--primary);
}

/* Newsletter CTA Banner */
.newsletter-banner {
  background-color: var(--primary);
  color: white;
  padding: 60px 0;
  text-align: center;
  margin: 40px 0;
}

.newsletter-banner h2 {
  font-size: 2rem;
  margin-bottom: 12px;
}

.newsletter-banner p {
  font-size: 1.1rem;
  margin-bottom: 24px;
  opacity: 0.9;
}

.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 0 auto;
  gap: 10px;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border-radius: var(--radius-full);
  border: none;
  font-size: 1rem;
  outline: none;
}

.privacy-note {
  display: block;
  font-size: 0.8rem;
  margin-top: 12px;
  opacity: 0.8;
}

/* Health Topics Carousel */
.topics-section {
  padding: 40px 0;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 30px;
}

.section-title {
  font-size: 1.75rem;
}

.carousel-container {
  position: relative;
  display: flex;
  align-items: center;
}

.topics-track {
  display: flex;
  gap: 30px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding-bottom: 20px;
  scrollbar-width: none; /* Firefox */
}

.topics-track::-webkit-scrollbar {
  display: none; /* Chrome */
}

.topic-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  min-width: 140px;
  scroll-snap-align: start;
  cursor: pointer;
}

.topic-image {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: var(--bg-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 4px solid transparent;
  transition: border-color 0.3s, transform 0.3s;
}

.topic-card:hover .topic-image {
  border-color: var(--primary);
  transform: scale(1.05);
}

.topic-image svg {
  width: 48px;
  height: 48px;
  fill: var(--primary);
}

.topic-label {
  font-weight: 600;
  text-align: center;
  color: var(--text-dark);
}

.carousel-btn {
  background: white;
  border: 1px solid var(--border);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: absolute;
  z-index: 10;
  box-shadow: var(--shadow-sm);
  transition: background 0.2s;
}

.carousel-btn:hover {
  background: var(--bg-subtle);
}

.btn-prev { left: -20px; }
.btn-next { right: -20px; }

/* Health Tools */
.tools-section {
  padding: 60px 0;
  background-color: var(--bg-card);
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
}

.tools-hub {
  background: var(--bg-subtle);
  padding: 40px;
  border-radius: var(--radius-lg);
}

.tools-hub h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.tools-hub p {
  color: var(--text-light);
  margin-bottom: 24px;
}

.tools-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 30px;
}

.tool-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  background: white;
  padding: 16px;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sm);
}

.tool-icon {
  width: 24px;
  height: 24px;
  color: var(--primary);
  flex-shrink: 0;
}

.tool-info h4 {
  font-size: 1.05rem;
  margin-bottom: 4px;
  color: var(--text-dark);
}
.tool-info p {
  font-size: 0.9rem;
  margin-bottom: 0;
}

/* Recommended Reads */
.recommended-section {
  padding: 60px 0;
}

.tabs {
  display: flex;
  gap: 12px;
  margin-bottom: 30px;
  overflow-x: auto;
  padding-bottom: 10px;
  scrollbar-width: none;
}
.tabs::-webkit-scrollbar { display: none; }

.tab {
  background: var(--bg-card);
  border: 1px solid var(--border);
  padding: 8px 20px;
  border-radius: var(--radius-full);
  font-weight: 600;
  color: var(--text-light);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s;
}

.tab.active, .tab:hover {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 30px;
}

.article-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s, transform 0.2s;
}

.article-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.article-img {
  height: 160px;
  background: var(--bg-subtle);
}

.article-content {
  padding: 20px;
}

.article-title {
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text-dark);
}

/* Trust Pillars */
.trust-section {
  background: var(--bg-card);
  padding: 60px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.trust-section h2 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 50px;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 30px;
}

.trust-pillar {
  text-align: center;
}

.trust-icon {
  width: 60px;
  height: 60px;
  background: var(--bg-subtle);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  color: var(--primary);
}

.trust-icon svg {
  width: 30px;
  height: 30px;
  fill: currentColor;
}

.trust-pillar h4 {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.trust-pillar p {
  font-size: 0.95rem;
  color: var(--text-light);
}

/* Featured & Videos */
.featured-section {
  padding: 60px 0;
}

.featured-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.featured-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  text-align: center;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 120px;
  border: 2px solid transparent;
  transition: border-color 0.2s;
}

.featured-card:hover {
  border-color: var(--primary);
}

.video-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  background: var(--bg-subtle);
  cursor: pointer;
}

.video-img {
  height: 180px;
  background: #E0E0E0;
}

.play-button {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 50px;
  height: 50px;
  background: rgba(0,0,0,0.6);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.play-button::after {
  content: '';
  display: block;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 10px 0 10px 16px;
  border-color: transparent transparent transparent white;
  margin-left: 4px;
}

.video-card:hover .play-button {
  background: var(--primary);
}

.video-content {
  padding: 16px;
  background: white;
}

.video-title {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
}

/* Footer */
footer {
  background: var(--text-dark);
  color: white;
  padding: 60px 0 30px;
}

.footer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  margin-bottom: 40px;
}

.footer-newsletter h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.footer-newsletter p {
  color: #B0B0B0;
  max-width: 500px;
  margin-bottom: 20px;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-bottom: 30px;
}

.footer-links a {
  color: white;
  font-weight: 500;
}
.footer-links a:hover {
  color: var(--primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #B0B0B0;
  font-size: 0.85rem;
}

.social-links {
  display: flex;
  gap: 16px;
}

.social-links a {
  color: white;
  font-size: 1.2rem;
}

@media (max-width: 900px) {
  .hero-grid, .tools-grid, .trust-grid, .featured-grid {
    grid-template-columns: 1fr;
  }
  .mega-menu {
    width: 90vw;
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 600px) {
  .footer-top, .footer-bottom {
    flex-direction: column;
    text-align: center;
    gap: 20px;
  }
  .newsletter-form {
    flex-direction: column;
  }
}

