/* Health Topics Carousel */
.topics-section {
  padding: 40px 0;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 30px;
}

.section-title {
  font-size: 1.75rem;
}

.carousel-container {
  position: relative;
  display: flex;
  align-items: center;
}

.topics-track {
  display: flex;
  gap: 30px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding-bottom: 20px;
  scrollbar-width: none; /* Firefox */
}

.topics-track::-webkit-scrollbar {
  display: none; /* Chrome */
}

.topic-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  min-width: 140px;
  scroll-snap-align: start;
  cursor: pointer;
}

.topic-image {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: var(--bg-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 4px solid transparent;
  transition: border-color 0.3s, transform 0.3s;
}

.topic-card:hover .topic-image {
  border-color: var(--primary);
  transform: scale(1.05);
}

.topic-image svg {
  width: 48px;
  height: 48px;
  fill: var(--primary);
}

.topic-label {
  font-weight: 600;
  text-align: center;
  color: var(--text-dark);
}

.carousel-btn {
  background: white;
  border: 1px solid var(--border);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: absolute;
  z-index: 10;
  box-shadow: var(--shadow-sm);
  transition: background 0.2s;
}

.carousel-btn:hover {
  background: var(--bg-subtle);
}

.btn-prev { left: -20px; }
.btn-next { right: -20px; }

/* Health Tools */
.tools-section {
  padding: 60px 0;
  background-color: var(--bg-card);
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
}

.tools-hub {
  background: var(--bg-subtle);
  padding: 40px;
  border-radius: var(--radius-lg);
}

.tools-hub h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.tools-hub p {
  color: var(--text-light);
  margin-bottom: 24px;
}

.tools-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 30px;
}

.tool-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  background: white;
  padding: 16px;
  border-radius: var(--radius-sm);
