  transform: translateY(-4px);
}

.article-img {
  height: 160px;
  background: var(--bg-subtle);
}

.article-content {
  padding: 20px;
}

.article-title {
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text-dark);
}

