.trust-section h2 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 50px;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 30px;
}

.trust-pillar {
  text-align: center;
}

.trust-icon {
  width: 60px;
  height: 60px;
  background: var(--bg-subtle);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  color: var(--primary);
}

.trust-icon svg {
  width: 30px;
  height: 30px;
  fill: currentColor;
}

.trust-pillar h4 {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.trust-pillar p {
  font-size: 0.95rem;
  color: var(--text-light);
}

/* Featured & Videos */
.featured-section {
  padding: 60px 0;
}

.featured-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.featured-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  text-align: center;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 120px;
  border: 2px solid transparent;
  transition: border-color 0.2s;
}

.featured-card:hover {
  border-color: var(--primary);
}

.video-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  background: var(--bg-subtle);
  cursor: pointer;
}

.video-img {
  height: 180px;
  background: #E0E0E0;
}

.play-button {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 50px;
  height: 50px;
  background: rgba(0,0,0,0.6);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.play-button::after {
  content: '';
  display: block;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 10px 0 10px 16px;
  border-color: transparent transparent transparent white;
  margin-left: 4px;
}

.video-card:hover .play-button {
  background: var(--primary);
}

.video-content {
  padding: 16px;
  background: white;
}

.video-title {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
}

/* Footer */
footer {
  background: var(--text-dark);
  color: white;
  padding: 60px 0 30px;
}

.footer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  margin-bottom: 40px;
}

.footer-newsletter h3 {
  font-size: 1.5rem;
  margin-bottom: 12px;
}

.footer-newsletter p {
  color: #B0B0B0;
  max-width: 500px;
  margin-bottom: 20px;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-bottom: 30px;
}

.footer-links a {
  color: white;
  font-weight: 500;
}
.footer-links a:hover {
  color: var(--primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #B0B0B0;
  font-size: 0.85rem;
}

.social-links {
  display: flex;
  gap: 16px;
}

.social-links a {
  color: white;
  font-size: 1.2rem;
}

@media (max-width: 900px) {
  .hero-grid, .tools-grid, .trust-grid, .featured-grid {
    grid-template-columns: 1fr;
  }
  .mega-menu {
    width: 90vw;
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 600px) {
  .footer-top, .footer-bottom {
    flex-direction: column;
    text-align: center;
    gap: 20px;
  }
  .newsletter-form {
    flex-direction: column;
  }
}

